//! Thumbnails and availability for file transfers (spec §5: "thumbnails
//! and previews generated by the sender, sent inline as small data";
//! "availability status on every file").
//!
//! **Sender-generated, always.** The spec says so and the reason is the
//! same one that governs link previews: a receiver that renders a preview
//! is a receiver that has decoded a file somebody else chose, before
//! deciding whether to accept it. Image decoders are a classic place for
//! memory-safety bugs, and "we only decoded it to make a thumbnail" is how
//! that becomes an exploit. Here the sender produces a tiny image from a
//! file they already have, and the receiver renders something small,
//! bounded and known-shaped.
//!
//! The thumbnail travels in the offer, so it has to be small enough to sit
//! in one control message alongside the rest. That bounds it far more
//! tightly than picture quality would -- see [`MAX_THUMBNAIL_BYTES`].
//!
//! [`Availability`] carries all three states the spec names, but only
//! `Available` is reachable today: telling the difference between a sender
//! who is offline and one who stopped sharing requires somewhere to ask
//! that is not the sender, which is spec §8's delivery routes. The wording
//! for the other two is written and tested so the distinction is settled
//! before anything depends on it.

use serde::{Deserialize, Serialize};

/// Largest thumbnail accepted, encoded.
///
/// The offer is one control message on a UDP path with a 4096-byte
/// datagram limit, and the rest of the offer needs room too. A preview
/// that does not fit is simply not sent -- growing the transport to carry
/// a nicer picture would be the tail wagging the dog.
pub const MAX_THUMBNAIL_BYTES: usize = 2048;

/// Longest edge of a generated thumbnail, in pixels.
pub const THUMBNAIL_EDGE: u32 = 64;

/// Whether the file this describes can still be fetched (spec §5's
/// "availability status on every file").
#[derive(Serialize, Deserialize, Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum Availability {
    /// The sender is here and holding it.
    #[default]
    Available,
    /// Known to exist, but nobody who has it is reachable right now.
    SenderOffline,
    /// The sender stopped sharing it.
    NoLongerShared,
}

impl Availability {
    /// Plain wording for the UI.
    ///
    /// Says what the user can *do*, not what the system's state is --
    /// "Available" alone tells someone nothing about whether waiting will
    /// help.
    pub fn describe(self) -> &'static str {
        match self {
            Availability::Available => "Ready to download.",
            Availability::SenderOffline => {
                "Nobody who has this file is online. It will download when they come back."
            }
            Availability::NoLongerShared => {
                "The person who sent this has stopped sharing it. It can't be downloaded again."
            }
        }
    }
}

/// Whether a filename looks like something worth previewing.
///
/// Extension-based rather than content-sniffing: this only decides whether
/// to *attempt* a thumbnail of a local file the user chose, so being wrong
/// costs a failed decode, not a security problem.
pub fn is_previewable(file_name: &str) -> bool {
    let lower = file_name.to_lowercase();
    [".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp"]
        .iter()
        .any(|ext| lower.ends_with(ext))
}

/// Generates a small PNG thumbnail of an image file.
///
/// Returns `None` when the file is not an image, cannot be decoded, or the
/// result would not fit -- all of which are ordinary outcomes rather than
/// errors. A transfer without a thumbnail works exactly as before.
pub fn generate(path: &std::path::Path) -> Option<Vec<u8>> {
    if !is_previewable(&path.to_string_lossy()) {
        return None;
    }
    let image = image::open(path).ok()?;
    let thumb = image.thumbnail(THUMBNAIL_EDGE, THUMBNAIL_EDGE);

    let mut encoded = Vec::new();
    thumb
        .write_to(&mut std::io::Cursor::new(&mut encoded), image::ImageFormat::Png)
        .ok()?;

    (encoded.len() <= MAX_THUMBNAIL_BYTES).then_some(encoded)
}

/// Checks a received thumbnail before it goes anywhere near a decoder.
///
/// The sender is not trusted: the size limit is enforced again here, and
/// the PNG magic number is checked, so a mislabelled blob is rejected
/// rather than handed to an image library.
pub fn accept_thumbnail(bytes: &[u8]) -> bool {
    const PNG_MAGIC: &[u8] = &[0x89, b'P', b'N', b'G', 0x0d, 0x0a, 0x1a, 0x0a];
    !bytes.is_empty() && bytes.len() <= MAX_THUMBNAIL_BYTES && bytes.starts_with(PNG_MAGIC)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn png_bytes(w: u32, h: u32) -> Vec<u8> {
        let img = image::RgbaImage::from_fn(w, h, |x, y| {
            image::Rgba([(x % 256) as u8, (y % 256) as u8, 128, 255])
        });
        let mut out = Vec::new();
        image::DynamicImage::ImageRgba8(img)
            .write_to(&mut std::io::Cursor::new(&mut out), image::ImageFormat::Png)
            .unwrap();
        out
    }

    fn write_temp(name: &str, bytes: &[u8]) -> std::path::PathBuf {
        let dir = std::env::temp_dir().join(format!("antiphon-preview-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join(name);
        std::fs::write(&path, bytes).unwrap();
        path
    }

    #[test]
    fn image_names_are_recognised_and_others_are_not() {
        for name in ["photo.png", "SCAN.JPG", "thing.jpeg", "anim.gif", "old.bmp"] {
            assert!(is_previewable(name), "{name} should be previewable");
        }
        for name in ["notes.txt", "archive.zip", "report.pdf", "clip.wav", "", "png"] {
            assert!(!is_previewable(name), "{name} should not be previewable");
        }
    }

    #[test]
    fn a_thumbnail_is_generated_and_is_small() {
        let path = write_temp("big.png", &png_bytes(512, 512));
        let thumb = generate(&path).expect("should produce a thumbnail");

        assert!(
            thumb.len() <= MAX_THUMBNAIL_BYTES,
            "thumbnail was {} bytes, limit is {MAX_THUMBNAIL_BYTES}",
            thumb.len()
        );
        assert!(accept_thumbnail(&thumb), "our own thumbnail should pass the receiver's check");
    }

    #[test]
    fn the_thumbnail_is_actually_smaller_than_the_original() {
        let original = png_bytes(512, 512);
        let path = write_temp("orig.png", &original);
        let thumb = generate(&path).unwrap();

        assert!(thumb.len() < original.len(), "thumbnail was not smaller");
    }

    #[test]
    fn a_non_image_produces_no_thumbnail_rather_than_an_error() {
        let path = write_temp("notes.txt", b"just some text");
        assert!(generate(&path).is_none());
    }

    #[test]
    fn a_file_that_lies_about_being_an_image_is_handled() {
        // Named .png, contents are not. A failed decode is an ordinary
        // outcome, not a crash.
        let path = write_temp("liar.png", b"definitely not a png");
        assert!(generate(&path).is_none());
    }

    #[test]
    fn a_receiver_rejects_anything_that_is_not_a_png() {
        // The sender is not trusted. A mislabelled blob must be refused
        // before it reaches an image decoder.
        assert!(!accept_thumbnail(b"GIF89a and then some"));
        assert!(!accept_thumbnail(b"<svg onload=alert(1)>"));
        assert!(!accept_thumbnail(&[]));
    }

    #[test]
    fn a_receiver_rejects_an_oversized_thumbnail() {
        // The limit is enforced again on receipt: the sender chose the
        // number in the offer, so it cannot be taken on trust.
        let mut oversized = vec![0x89, b'P', b'N', b'G', 0x0d, 0x0a, 0x1a, 0x0a];
        oversized.resize(MAX_THUMBNAIL_BYTES + 1, 0);
        assert!(!accept_thumbnail(&oversized));
    }

    #[test]
    fn the_wording_says_whether_waiting_will_help() {
        // The difference that matters to someone staring at a stuck file:
        // one of these is worth waiting out, the other never will be.
        assert!(Availability::SenderOffline.describe().contains("come back"));
        assert!(Availability::NoLongerShared.describe().contains("can't be downloaded"));
    }

    #[test]
    fn every_availability_state_explains_itself() {
        for state in [
            Availability::Available,
            Availability::SenderOffline,
            Availability::NoLongerShared,
        ] {
            assert!(!state.describe().is_empty(), "{state:?} has no wording");
        }
    }

    #[test]
    fn availability_round_trips_through_json() {
        for state in [
            Availability::Available,
            Availability::SenderOffline,
            Availability::NoLongerShared,
        ] {
            let json = serde_json::to_string(&state).unwrap();
            assert_eq!(serde_json::from_str::<Availability>(&json).unwrap(), state);
        }
    }
}
